package com.aiservice.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ai_settings") public class AiSettingsEntity { @Id public UUID id; @Column(nullable=false,length=20) public String provider; @Column(nullable=false,length=160) public String model; @Column(name="api_key_encrypted",columnDefinition="TEXT") public String apiKeyEncrypted; @Column(name="updated_at",nullable=false) public Instant updatedAt; @Column(name="updated_by",nullable=false) public UUID updatedBy; @Column(name="last_checked_at") public Instant lastCheckedAt; @Column(name="last_error_code",length=100) public String lastErrorCode; @Column(name="runtime_status",nullable=false,length=40) public String runtimeStatus = "CONFIGURED_BUT_UNVERIFIED"; }
